const RATIOS = {
  "1:1 Unison Ring": [1, 1],
  "3:2 Fifth Torus": [3, 2],
  "4:3 Quartic Cage": [4, 3],
  "5:2 Pentagram Mesh": [5, 2],
  "7:4 Septic Braid": [7, 4],
  "9:5 Anharmonic Knot": [9, 5]
};

const MOD_DEPTH = {
  "Pure Sine Sweep": 0,
  "Subtle Ripple": 0.1,
  "Folded Ribbons": 0.3,
  "Deep Waveform Shear": 0.6,
  "Spastic Churn": 1.0,
  "Turbulent Rupture": 1.8
};

const BLANKING = {
  "Continuous Trace": [],
  "Stitched Dashes": [40, 20],
  "Segmented Strobe": [10, 50],
  "Syncopated Bursts": [50, 10, 10, 10, 10, 10],
  "Needle Spikes": [2, 40],
  "Sparse Photon Ticks": [4, 80]
};

const DECAY = {
  "Crisp Monochrome Strike": 255,
  "Short Retinal Ghost": 120,
  "Luminous Afterglow": 45,
  "Dense Smear Reservoir": 15,
  "Saturated Phosphor Fog": 12,
  "Infinite Trace Burn": 8
};

const ASTIGMATISM = {
  "Razor Focus Needle": { weight: 2, jitter: 0 },
  "Tuned Gaussian Core": { weight: 2, jitter: 0 },
  "Soft Electron Halo": { weight: 3, jitter: 0 },
  "Overdriven Line Bloom": { weight: 5, jitter: 0 },
  "Deflection Jitter Blur": { weight: 3, jitter: 8 },
  "Cathode Corona Spill": { weight: 7, jitter: 15 }
};

p.setup = function() {
  p.createCanvas(800, 800);
  p.background(0);
};

p.draw = function() {
  const vRatio = p.getSynthVar('carrier_ratio') || '1:1 Unison Ring';
  const vMod = p.getSynthVar('modulation_depth') || 'Pure Sine Sweep';
  const vBlank = p.getSynthVar('blanking_cadence') || 'Continuous Trace';
  const vDecay = p.getSynthVar('phosphor_decay') || 'Crisp Monochrome Strike';
  const vAstig = p.getSynthVar('beam_astigmatism') || 'Razor Focus Needle';

  const rx = RATIOS[vRatio][0];
  const ry = RATIOS[vRatio][1];
  const mod = MOD_DEPTH[vMod];
  const dash = BLANKING[vBlank];
  const decayAlpha = DECAY[vDecay];
  const astig = ASTIGMATISM[vAstig];

  p.drawingContext.setLineDash([]);
  p.drawingContext.shadowBlur = 0;
  p.fill(0, decayAlpha);
  p.noStroke();
  p.rect(0, 0, p.width, p.height);

  p.push();
  p.translate(p.width / 2, p.height / 2);

  if (astig.jitter > 0) {
    p.translate(p.random(-astig.jitter, astig.jitter), p.random(-astig.jitter, astig.jitter));
  }

  const numPoints = 140;
  const time = p.frameCount * 0.025;
  const vertices = [];

  for (let i = 0; i < numPoints; i++) {
    let t = i * 0.34; 

    let bx = p.sin(t * rx + time);
    let by = p.cos(t * ry + time * 0.85);

    let mx = p.sin(t * rx * 2.5 - time * 1.5) * mod;
    let my = p.cos(t * ry * 2.5 - time * 1.5) * mod;

    let baseX = (bx + mx) * 220;
    let baseY = (by + my) * 220;

    let z = p.sin(t * (rx + ry) * 0.4 + time) * 120;
    let scale = 350 / (350 - z);

    vertices.push({ x: baseX * scale, y: baseY * scale });
  }

  p.noFill();
  p.strokeWeight(astig.weight);

  // Faint continuous baseline trace to guarantee 1.2% canvas coverage
  p.drawingContext.setLineDash([]);
  p.stroke(180, 255, 180, 30);
  p.beginShape();
  for (let i = 0; i < numPoints; i++) {
    p.vertex(vertices[i].x, vertices[i].y);
  }
  p.endShape();

  // Sharp core dashed stroke
  p.drawingContext.setLineDash(dash);
  p.stroke(180, 255, 180, 220);
  p.beginShape();
  for (let i = 0; i < numPoints; i++) {
    p.vertex(vertices[i].x, vertices[i].y);
  }
  p.endShape();

  p.pop();
};
